"""Reproducible PDF catalog. Hand-checked examples anchor generated edge cases.
Run from the repository root: python3 scripts/build_catalog.py
"""
import json, pathlib, io, contextlib, math, re
ROOT=pathlib.Path(__file__).resolve().parents[1]
problems=[]
COMMON='''import sys, math
from collections import Counter
raw=sys.stdin.read().strip()
tokens=raw.split()
def prime(x):
    return x>=2 and all(x%d for d in range(2,math.isqrt(x)+1))
def emit(a):
    print(' '.join(map(str,a)))
def divisors(n):
    return [x for x in range(1,n) if n%x==0]
'''
def output(code, data):
    old=__import__('sys').stdin; __import__('sys').stdin=io.StringIO(data)
    out=io.StringIO()
    try:
        with contextlib.redirect_stdout(out):exec(code, {})
    finally:__import__('sys').stdin=old
    return out.getvalue().rstrip()
def add(level,num,title,desc,body,sample,expected,cases,fmt='A single integer n.',constraints='-100000 <= n <= 100000.',outfmt='Print the result exactly as shown in the examples.',prefix='n=int(tokens[0])\n',note=''):
    code=COMMON+prefix+body+'\n'
    sample=str(sample); expected=str(expected)
    actual=output(code,sample)
    assert actual==expected,(level,num,actual,expected)
    inputs=list(dict.fromkeys([sample]+[str(c) for c in cases]))
    assert len(inputs)>=6,(level,num,'need six distinct cases')
    tests=[dict(input=v,expected_output=output(code,v),test_type='basic' if i==0 else ['valid','edge','large','special','random'][(i-1)%5],is_hidden=i>0) for i,v in enumerate(inputs)]
    legacy={1:'fibonacci-series',2:'smallest-prime-number',3:'prime-or-composite-number',4:'series-sum-calculator',5:'divisor-sum-and-equality-checker',6:'abundant-number',7:'leap-and-non-leap-years',8:'geometric-series-sum-calculator',9:'sum-of-squares-of-n-natural-numbers',10:'harmonic-series',11:'digits-count',49:'reverse-the-digits'}
    slug=legacy.get(num) if level==2 else None
    slug=slug or f'level-{level}-{num:02}-'+re.sub('[^a-z0-9]+','-',title.lower()).strip('-')
    problems.append(dict(source=f'Level {level}',source_number=num,problem_number=num if level==2 else 57+num,title=title,slug=slug,difficulty='Easy' if level==2 else 'Medium',category=f'Level {level}'+(' — Arrays' if level==3 else ' — Loops & Numbers'),tags=[f'level-{level}','array' if level==3 else 'loops'],description=f'Level {level} · Question {num}\n\n'+desc+ ('\n\nClarification: '+note if note else ''),constraints=constraints,input_format=fmt,output_format=outfmt,reference_solution=code,examples=[dict(input=sample,output=expected,explanation='Sample for the contract above.')],tests=tests))
def l2(n,title,desc,body,sample,expected,cases,**kw):add(2,n,title,desc,body,sample,expected,cases,**kw)
