# Array contracts: whitespace-separated output, explicit indexing, stable order.
ARRAY='n=int(tokens[0])\na=list(map(int,tokens[1:1+n]))\ntail=list(map(int,tokens[1+n:]))\n'
def arr(a,*tail):return str(len(a))+'\n'+' '.join(map(str,a))+('\n'+' '.join(map(str,tail)) if tail else '')
standard=[[7],[0,0,0],[-5,-1,-9],[3,1,3,2,1],[1,2,3,4,5],list(range(99,-1,-1))]
def l3(n,title,desc,body,sample,expected,cases=None,**kw):
    kw.setdefault('prefix',ARRAY);kw.setdefault('fmt','Integer n, followed by n integers. Read across any whitespace.')
    kw.setdefault('constraints','1 <= n <= 100; -1000 <= array values <= 1000.')
    kw.setdefault('outfmt','Separate array values by spaces. Print no prompts, brackets, or commas unless specified. An empty result is an empty line.')
    add(3,n,title,desc,body,sample,expected,cases if cases is not None else [arr(a) for a in standard],**kw)
