l3(2,'Finding the Maximum Number','Print the largest array value.',"print(max(a))",arr([2,52,86,489,21]),489)
l3(3,'Peak Elements','A peak is at least as large as its existing neighbors. Print the first endpoint if a peak, then the last endpoint if a peak, then internal peaks from left to right. A singleton is printed once.',"if n==1:emit(a)\nelse:\n    r=([a[0]] if a[0]>=a[1] else [])+([a[-1]] if a[-1]>=a[-2] else [])\n    r += [a[i] for i in range(1,n-1) if a[i]>=a[i-1] and a[i]>=a[i+1]]\n    emit(r)",arr([7,6,5,6,7,9]),'7 9',note='Endpoint-first ordering matches the answer code; equal neighbors qualify.')
