l3(23,'Pair with Sum Closest to Zero','For array length outside 2..10 print Invalid. Otherwise choose distinct indices i<j minimizing abs(a[i]+a[j]). Ties choose the smallest i, then smallest j. Print the two values.',"if not 2<=n<=10:print('Invalid')\nelse:\n    i,j=min(((i,j) for i in range(n) for j in range(i+1,n)),key=lambda ij:(abs(a[ij[0]]+a[ij[1]]),ij))\n    print(a[i],a[j])",arr([-1,-10,8,2]),'-1 2',[arr([1]),arr(list(range(11))),arr([-5,5]),arr([1,2,3]),arr([-8,-2,-1]),arr([-2,2,-1,1]),arr([0,0,5])],constraints='0 <= n <= 100; -1000 <= values <= 1000.',note='The 2..10 restriction is applied to length. Applying it to values would contradict the PDF example with -10 and -1.')
l3(24,'Median','Print the sorted array, then its median to six decimal places. For even length take the arithmetic mean of the two middle values.',"a.sort();emit(a);print(f'{(a[n//2] if n%2 else (a[n//2-1]+a[n//2])/2):.6f}')",arr([7,8,9,64,21,32]),'7 8 9 21 32 64\n15.000000',[arr([1,2]),arr([7]),arr([-3,-2]),arr([3,1,2]),arr([2,2,2,2]),arr(list(range(100)))],note='Fractional medians are preserved; the source accidentally uses integer division.')
l3(25,'Chunk Size','Split the array into consecutive chunks of at most k elements. Print adjacent bracketed comma-separated chunks with no spaces, e.g. [1,2][3]. For k <= 0 print Invalid.',"k=tail[0]\nprint(''.join('['+','.join(map(str,a[i:i+k]))+']' for i in range(0,n,k)) if k>0 else 'Invalid')",arr([10,52,85,63,41],2),'[10,52][85,63][41]',[arr([7],1),arr([1,2,3],1),arr([1,2,3],3),arr([1,2,3],5),arr([1,2],0),arr([1,2],-1),arr(list(range(100)),9)],fmt='n, n values, then chunk size k.')
l3(26,'Insert at a Particular Position','Insert value x at 1-based position p (1..n+1). If p is invalid print Invalid.',"x,p=tail\nif 1<=p<=n+1:a.insert(p-1,x);emit(a)\nelse:print('Invalid')",arr([1,4,7,8,5],2,3),'1 4 2 7 8 5',[arr([7],9,1),arr([7],9,2),arr([1,2,3],0,2),arr([1,2],5,0),arr([1,2],5,4),arr(list(range(100)),1000,101)],fmt='n, n values, then value x and 1-based position p.')
