l3(41,'Product of Array Except Self','For each position print the product of every other element. Do not divide by the current value. The empty product for a singleton is 1.',"emit(math.prod(a[:i]+a[i+1:]) for i in range(n))",arr([1,2,3,4,5]),'120 60 40 30 24',productcases+[arr([0,0,2])],constraints='1 <= n <= 100; -1000 <= values <= 1000; products fit signed 64-bit integers.')
