notes=['# PDF question catalog','', 'All 57 Level 2 questions and all 52 Level 3 questions are included. Original numbering is shown in each description. Platform numbers 1–57 are Level 2; 58–109 are Level 3. Existing problem IDs/slugs are preserved by seeding.','', 'Each reference is checked against a hand-entered example. Deterministic hidden inputs cover edge cases and larger values. These are hidden from the student API, not secret from repository owners. Do not publish the backend catalog if test secrecy from source readers is required.','', '## Judging conventions','', 'Read stdin without interactive prompts. Array outputs use spaces, not concatenated digits. Line breaks distinguish output sections and pattern rows. Trailing whitespace is ignored. C/C++ solutions should use 64-bit integers where constraints require them; Java solutions use Main. No language receives starter code.','', '## Source ambiguities and corrections','']
for p in problems:
 if 'Clarification:' in p['description']:notes.append(f"- **{p['source']} Q{p['source_number']} — {p['title']}:** "+p['description'].split('Clarification: ')[1])
notes+=['','## Complete mapping','','| PDF | Question | Platform # | Title | Hidden cases |','|---|---:|---:|---|---:|']
for p in problems:notes.append(f"| {p['source']} | {p['source_number']} | {p['problem_number']} | {p['title']} | {sum(t['is_hidden'] for t in p['tests'])} |")
(ROOT/'docs').mkdir(exist_ok=True);(ROOT/'docs/pdf-catalog.md').write_text('\n'.join(notes)+'\n')
